CREATE TABLE "public"."suppliers" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"       text                     NOT NULL,
  "category"   text                     NOT NULL DEFAULT 'Inne'::text,
  "phone"      text,
  "hours"      text,
  "address"    text,
  "notes"      text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "suppliers_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."suppliers"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "suppliers_all_staff" ON "public"."suppliers"
  FOR ALL
  TO PUBLIC
  USING ((public.current_role_name() IS NOT NULL))
  WITH CHECK ((public.current_role_name() IS NOT NULL));

REVOKE ALL ON SEQUENCE "public"."suppliers_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."suppliers_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."suppliers_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."suppliers_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."suppliers_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."suppliers_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."suppliers_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."suppliers_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."suppliers" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."suppliers" TO "service_role";

REVOKE ALL ON TABLE "public"."suppliers" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."suppliers" TO "postgres";
